/**
 * Embedded DOCX template
 *
 * This is a base64-encoded blank DOCX file created with Microsoft Word.
 * It provides the complete schema, styles, themes, and fonts needed to
 * initialize SuperDoc when working with HTML or JSON content.
 *
 * The DOCX contains all standard Word document components:
 * - [Content_Types].xml
 * - _rels/.rels
 * - word/document.xml
 * - word/_rels/document.xml.rels
 * - word/styles.xml (full Word styles)
 * - word/settings.xml
 * - word/fontTable.xml
 * - word/webSettings.xml
 * - word/theme/theme1.xml
 * - docProps/core.xml
 * - docProps/app.xml
 */

/**
 * Base64-encoded blank DOCX file created with Microsoft Word.
 */
const BLANK_DOCX_BASE64 = ``;

/**
 * Convert base64 string to Blob
 */
function base64ToBlob(base64: string, mimeType: string): Blob {
  const byteCharacters = atob(base64.replace(/\s/g, ''));
  const byteNumbers = new Array(byteCharacters.length);

  for (let i = 0; i < byteCharacters.length; i++) {
    byteNumbers[i] = byteCharacters.charCodeAt(i);
  }

  const byteArray = new Uint8Array(byteNumbers);
  return new Blob([byteArray], { type: mimeType });
}

/**
 * Convert base64 string to File
 */
function base64ToFile(base64: string, filename: string, mimeType: string): File {
  const blob = base64ToBlob(base64, mimeType);
  return new File([blob], filename, { type: mimeType });
}

/**
 * Get the blank DOCX template as a File object
 */
export function getBlankTemplateFile(): File {
  return base64ToFile(
    BLANK_DOCX_BASE64,
    'blank-template.docx',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  );
}

/**
 * Get the blank DOCX template as a Blob
 */
export function getBlankTemplateBlob(): Blob {
  return base64ToBlob(
    BLANK_DOCX_BASE64,
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  );
}

/**
 * Check if a File is a valid DOCX file (basic check)
 */
export function isValidDocxFile(file: File): boolean {
  const validTypes = [
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/msword',
  ];
  return validTypes.includes(file.type) || file.name.endsWith('.docx');
}
